def rd(n): return pd.read_csv(R/n)
def save(fig,name,folder=MAIN,data=None):
    fig.tight_layout(); fig.savefig(folder/(name+'.pdf'),bbox_inches='tight'); fig.savefig(folder/(name+'.png'),dpi=600,bbox_inches='tight'); plt.close(fig)
    if data is not None: data.to_csv(FD/(name+'.csv'),index=False)
def latex(df,path,caption,label):
    x=df.copy();
    for c in x.select_dtypes(include='number'): x[c]=x[c].map(lambda v:'NA' if pd.isna(v) else f'{v:.4f}')
    path.write_text(x.to_latex(index=False,escape=True,caption=caption,label=label,float_format='%.4f'),encoding='utf-8')
def table(df,n,caption):
    df.to_csv(T/(n+'.csv'),index=False); latex(df,T/(n+'.tex'),caption,'tab:'+n)
def heat(df,name,title,folder=SUP,stars=None):
    fig,ax=plt.subplots(figsize=(7.1,3.3)); im=ax.imshow(df.values.astype(float),cmap='cividis',vmin=0,vmax=1,aspect='auto')
    ax.set_xticks(range(len(df.columns)),df.columns,rotation=30,ha='right'); ax.set_yticks(range(len(df.index)),df.index)
    for i in range(len(df.index)):
      for j in range(len(df.columns)):
        v=df.iloc[i,j]; ax.text(j,i,f'{v:.2f}'+('*' if stars and stars.get(df.index[i])==df.columns[j] else ''),ha='center',va='center',fontsize=6,color='white' if v<.3 else 'black')
    ax.set_title(title,fontsize=9); fig.colorbar(im,ax=ax,label='Rate'); save(fig,name,folder,df.reset_index())
def diagram(name,columns,footer=''):
    fig,ax=plt.subplots(figsize=(7.1,4.4)); ax.axis('off')
    xs=np.linspace(.08,.92,len(columns)); colors=['#DCEAF7','#E8F3E8','#FCE8DE']
    for ci,(head,items) in enumerate(columns):
      x=xs[ci]; ax.text(x,.96,head,ha='center',weight='bold',color=['#0072B2','#009E73','#D55E00'][ci%3],transform=ax.transAxes)
      ys=np.linspace(.84,.16,len(items))
      for k,(y,item) in enumerate(zip(ys,items)):
        box=FancyBboxPatch((x-.105,y-.035),.21,.07,boxstyle='round,pad=.008',fc=colors[ci%3],ec='#444',lw=.8,transform=ax.transAxes)
        ax.add_patch(box); ax.text(x,y,item,ha='center',va='center',fontsize=6.5,transform=ax.transAxes)
        if k<len(items)-1: ax.annotate('',(x,ys[k+1]+.04),(x,y-.04),arrowprops={'arrowstyle':'->','lw':.8},xycoords=ax.transAxes)
      if ci<len(columns)-1: ax.annotate('',(xs[ci+1]-.12,.5),(x+.12,.5),arrowprops={'arrowstyle':'->','lw':1.2},xycoords=ax.transAxes)
    if footer: ax.text(.5,.035,footer,ha='center',color='#A33',weight='bold',fontsize=7,transform=ax.transAxes)
    save(fig,name,DIA)

